const out = [];
for (const item of $input.all()) {
  const rows = Array.isArray(item.json) ? item.json : (item.json.data || item.json.signals || []);
  for (const row of rows) {
    const text = row.text || row.message || JSON.stringify(row);
    out.push({
      json: {
        channel: 'api',
        external_chat_id: 'smc_auto_trender',
        external_message_id: String(row.id ?? ''),
        sender: 'smc_auto_trender',
        raw_text: text,
        raw_payload: row,
        received_at: new Date().toISOString(),
        is_test: false
      }
    });
  }
}
return out;

// Deterministic sample so the full pipeline can be exercised without
// touching a real source or a real client-facing channel. "Test Mode
// Check" downstream skips the real Telegram/WhatsApp sends for is_test
// items.
//
// Before running: register a signal_sources row for this fixture, e.g.
//   insert into signal_sources (slug, name, kind, telegram_chat_id, is_active)
//   values ('test-fixture', 'Test Fixture', 'manual', 'TEST_FIXTURE', true);
const text = 'BUY BANKNIFTY 51000 CE above 420, SL 380, Target1 460 Target2 500. Intraday view, 30-45 min timeframe.';
const id = `test-${Date.now()}`;
return [{
  json: {
    channel: 'telegram',
    external_chat_id: 'TEST_FIXTURE',
    external_message_id: id,
    sender: 'test_harness',
    raw_text: text,
    raw_payload: { source: 'test_mode_trigger' },
    received_at: new Date().toISOString(),
    is_test: true
  }
}];

const VALID_CATEGORIES = ['F&O','EQUITY','COMMODITY','IPO','SIP','MUTUAL_FUND','INVESTMENT','INSURANCE','LOAN','MARKET_UPDATE','EDUCATION','OTHER'];
const TRADE_CATEGORIES = ['F&O','EQUITY','COMMODITY'];
const num = (v) => (v === null || v === undefined || v === '' || isNaN(Number(v))) ? null : Number(v);

const out = [];
for (const item of $input.all()) {
  const rm = $('Insert Raw Message').item.json;
  const isTest = $('Merge All Sources').item.json.is_test === true;
  const raw = item.json.output ?? item.json;

  let p;
  try {
    p = typeof raw === 'string' ? JSON.parse(raw) : raw;
  } catch (e) {
    p = { is_signal: false, category: 'OTHER', normalized_message: rm.raw_text, _parse_error: `AI output was not valid JSON: ${e.message}` };
  }

  const category = VALID_CATEGORIES.includes(p.category) ? p.category : 'OTHER';
  const isTradeCategory = TRADE_CATEGORIES.includes(category);
  const action = (p.action === 'BUY' || p.action === 'SELL') ? p.action : null;
  const targets = Array.isArray(p.targets) ? p.targets.map(num).filter((v) => v !== null) : [];
  const entry = num(p.entry);
  const stopLoss = num(p.stop_loss);
  const confidence = num(p.confidence);

  let validationReason = null;
  if (p._parse_error) validationReason = p._parse_error;
  else if (p.is_signal !== true) validationReason = 'AI classified this as not a signal.';
  else if (!p.symbol) validationReason = 'No symbol/instrument identified.';
  else if (isTradeCategory && !action) validationReason = 'Trade category but no clear BUY/SELL action.';
  else if (entry !== null && stopLoss !== null && entry === stopLoss) validationReason = 'Entry and stop-loss are identical.';
  else if (confidence !== null && (confidence < 0 || confidence > 100)) validationReason = 'Confidence out of range.';
  const valid = validationReason === null;

  const today = new Date().toISOString().slice(0, 10);
  const fingerprintSource = [category, p.symbol, action, entry, stopLoss, targets.join(',')]
    .map((v) => (v === null || v === undefined) ? '' : String(v))
    .join('|')
    .toUpperCase();
  const fingerprint = `${today}|${fingerprintSource}`;

  out.push({
    json: {
      valid,
      validation_reason: validationReason,
      category,
      is_trade_category: isTradeCategory,
      instrument: p.instrument ?? null,
      symbol: p.symbol ?? null,
      exchange: p.exchange ?? null,
      action,
      entry,
      stop_loss: stopLoss,
      target_1: targets[0] ?? null,
      target_2: targets[1] ?? null,
      target_3: targets[2] ?? null,
      expiry: p.expiry ?? null,
      timeframe: p.timeframe ?? null,
      confidence,
      rationale: p.rationale ?? null,
      raw_message: rm.raw_text,
      normalized_message: p.normalized_message ?? rm.raw_text,
      fingerprint,
      raw_message_id: rm.id,
      source_id: rm.source_id,
      channel: rm.channel,
      source_message_id: rm.external_message_id,
      source_timestamp: rm.received_at,
      is_test: isTest
    }
  });
}
return out;
